// _ONE_PRODUCT_v1_: what the CLI and its agent know, shipped with the release — never fetched from a page at run time:
//   knowledge/coord-lang/   generated by `coord gen` from taifoon-io/coord (row cli-knowledge): the language's grounding pack, the
//                           studio blocks, the workflow check (check-lib.mjs) and its golden set (cases.json); GENERATED.json names
//                           the coord commit
//   knowledge/skills/       the public skill catalog of this repository (scripts/knowledge-skills.mjs, INDEX.json pins each sha256)
//   + for an admin only: the operator skills of a local coord checkout (COORD_HOME, default ~/projects/coord), read in place
// Reads are path-jailed: a topic resolves only to a file listed in an index, never to a path a caller names.
import { existsSync, readFileSync, readdirSync } from 'node:fs';
import { homedir } from 'node:os';
import { join } from 'node:path';

const PKG = new URL('..', import.meta.url).pathname;
const K = join(PKG, 'knowledge');
const MAX = 20_000;

function operatorSkills(env) {
  const home = env.COORD_HOME || join(homedir(), 'projects', 'coord');
  const dir = join(home, 'skills');
  if (!existsSync(dir)) return [];
  return readdirSync(dir).filter((n) => existsSync(join(dir, n, 'SKILL.md'))).map((n) => ({ topic: `operator/${n}`, path: join(dir, n, 'SKILL.md'), kind: 'operator-skill' }));
}

/** every document the caller may read: [{ topic, path, kind }] */
export function index({ role = 'public', env = process.env } = {}) {
  const docs = [];
  const lang = join(K, 'coord-lang');
  if (existsSync(join(lang, 'llms-coord-language.txt'))) docs.push({ topic: 'language', path: join(lang, 'llms-coord-language.txt'), kind: 'grounding' });
  if (existsSync(join(lang, 'studio-blocks.json'))) docs.push({ topic: 'studio-blocks', path: join(lang, 'studio-blocks.json'), kind: 'grounding' });
  const sk = join(K, 'skills', 'INDEX.json');
  if (existsSync(sk)) for (const s of JSON.parse(readFileSync(sk, 'utf8')).skills) docs.push({ topic: s.name, path: join(K, 'skills', s.file), kind: 'skill' });
  if (role === 'admin') docs.push(...operatorSkills(env));
  return docs;
}

const titleOf = (text) => (text.match(/^title:\s*"?([^"\n]+)/m)?.[1] ?? text.match(/^#\s+(.+)$/m)?.[1] ?? '').trim();
const descOf = (text) => (text.match(/^description:\s*"?([^\n]+?)"?$/m)?.[1] ?? '').trim();

/** search by words; the best documents with their best lines. args { query, limit } */
export async function knowledgeSearch({ query, limit } = {}, deps = {}) {
  const q = String(query ?? '').toLowerCase().split(/[^a-z0-9_.@/-]+/).filter((w) => w.length > 1);
  if (!q.length) return { ok: false, error: 'query: a few words (e.g. "stream my contract events")' };
  const n = Math.min(10, Math.max(1, Number(limit) || 5));
  const hits = [];
  for (const d of index({ role: deps.role, env: deps.env })) {
    const text = readFileSync(d.path, 'utf8'); const low = text.toLowerCase();
    let score = 0; for (const w of q) { let i = -1; let c = 0; while ((i = low.indexOf(w, i + 1)) >= 0 && c < 50) c++; score += c * (d.topic.includes(w) ? 3 : 1); }
    if (!score) continue;
    const lines = text.split('\n').map((l, i) => ({ i: i + 1, l, s: q.reduce((a, w) => a + (l.toLowerCase().includes(w) ? 1 : 0), 0) })).filter((x) => x.s).sort((a, b) => b.s - a.s).slice(0, 4).map((x) => `${x.i}: ${x.l.slice(0, 220)}`);
    hits.push({ topic: d.topic, kind: d.kind, title: titleOf(text), about: descOf(text).slice(0, 300), score, lines });
  }
  hits.sort((a, b) => b.score - a.score);
  return { ok: true, query, results: hits.slice(0, n), searched: index({ role: deps.role, env: deps.env }).length };
}

/** one document by its topic (from knowledge_search or `taifoon docs`). args { topic } */
export async function knowledgeGet({ topic } = {}, deps = {}) {
  const d = index({ role: deps.role, env: deps.env }).find((x) => x.topic === String(topic ?? ''));
  if (!d) return { ok: false, error: `no topic ${topic}: taifoon docs lists them` };
  const text = readFileSync(d.path, 'utf8');
  return { ok: true, topic: d.topic, kind: d.kind, title: titleOf(text), text: text.length > MAX ? `${text.slice(0, MAX)}\n… (${text.length - MAX} more characters)` : text };
}

/** the topics: { ok, topics: [{ topic, kind, title }] } */
export async function knowledgeList(_args = {}, deps = {}) {
  return { ok: true, topics: index({ role: deps.role, env: deps.env }).map((d) => ({ topic: d.topic, kind: d.kind, title: titleOf(readFileSync(d.path, 'utf8')) })) };
}

/**
 * Check a studio workflow against the language: steps are block ids (comma separated or an array), grant the outlets held, outlet
 * the one a write uses, ends_at the state it must end in. The same function as coord's golden set (knowledge/coord-lang/check-lib.mjs).
 */
export async function workflowCheck({ steps, grant, outlet, ends_at } = {}) {
  const lib = join(K, 'coord-lang', 'check-lib.mjs');
  if (!existsSync(lib)) return { ok: false, error: 'this release ships no workflow check (knowledge/coord-lang is missing)' };
  const { check } = await import(new URL(`file://${lib}`).href);
  const { blocks } = JSON.parse(readFileSync(join(K, 'coord-lang', 'studio-blocks.json'), 'utf8'));
  const list = Array.isArray(steps) ? steps.map(String) : String(steps ?? '').split(',').map((s) => s.trim()).filter(Boolean);
  if (!list.length) return { ok: false, error: 'steps: block ids, comma separated (taifoon docs get studio-blocks lists them)' };
  const g = Array.isArray(grant) ? grant : String(grant ?? '').split(',').map((s) => s.trim()).filter(Boolean);
  const why = check(list, { grant: g, outlet: outlet || null, ends_at: ends_at || null }, blocks);
  return { ok: true, valid: why.length === 0, why, steps: list, grant: g };
}

/** the golden set, run in this package's tests: every expected workflow passes, every wrong answer is refused */
export async function goldenSet() {
  const cases = JSON.parse(readFileSync(join(K, 'coord-lang', 'cases.json'), 'utf8'));
  const out = [];
  for (const c of cases.cases) { const r = await workflowCheck({ steps: c.expected, grant: c.grant, outlet: c.outlet, ends_at: c.ends_at }); out.push({ id: c.id, want: 'pass', got: r.valid ? 'pass' : 'fail', why: r.why }); }
  for (const x of cases.wrong_answers ?? []) { const c = cases.cases.find((y) => y.id === x.case); const r = await workflowCheck({ steps: x.answer, grant: x.grant ?? c.grant, outlet: c.outlet, ends_at: c.ends_at }); out.push({ id: `wrong:${x.case}`, want: 'refused', got: r.valid ? 'not refused' : 'refused', why: r.why }); }
  return out;
}
